// /app/app/coin-faces.js — reliable two-sided artwork for every flipping coin.
//
// A coin is two culled planes in ONE 3D rendering context: the red face at +z and the ETH face
// at -z, turned half a revolution so its art is upright when the coin shows its back. Chromium's
// compositor culls whichever plane faces away, from the same transform it draws, every frame.
// Face selection and motion therefore share one clock with no JavaScript at all: the spin stays
// on the compositor, keeps going through main-thread stalls, and costs no style work.
//
// ⛔ The one way to break it is to FLATTEN the 3D context. filter, opacity < 1, isolation,
// contain: paint, overflow other than visible, clip-path, mask or mix-blend-mode on the rotor,
// the surface or a face collapses the planes into one layer; culling then never fires and the
// red face's reverse (the "upside-down WWXRP") shows on every back-facing half-turn. Glow and
// shadow belong on the rotor's parent, which is outside the context and safe.
//
// History, so neither earlier design comes back:
// - Two planes once showed the upside-down face. Measured cause: a flattening property on the
//   chain, not culling itself. db/coin-face-stress.mjs reproduces it on demand (variants v6/v7).
// - A single plane with artwork swapped from requestAnimationFrame raced the compositor: the
//   plane turned over before the main thread swapped the art (variant v1, ~40% bad frames under
//   load). Locking the animation clock to the main thread fixed the race but paid a forced style
//   read every frame and froze the coin whenever the main thread stalled.
// Measured on a GeForce GPU and the software compositor, spin and tumble, main thread jammed:
// zero reversed frames for the culled design (v4/v5/v9); run the stress script after any change.

const FRONT = 'red';
const BACK = 'eth';
const EDGE_EPSILON = 0.0001;

/**
 * Which side of a transformed plane faces the viewer. Not used for rendering (the compositor
 * decides that); kept for callers and tests that reason about a pose.
 *
 * CSS usually serializes rotateX poses as matrix3d(). Some Chromium paths flatten a pose to
 * matrix(), where the 2D determinant keeps the orientation. At the exact edge the prior side holds.
 */
export function coinSideFromTransform(transform, previous = FRONT) {
  const prior = previous === BACK ? BACK : FRONT;
  const text = String(transform || '').trim();
  if (!text || text === 'none') return FRONT;

  const match = text.match(/^matrix3d\((.*)\)$/i);
  if (match) {
    const values = match[1].split(',').map((value) => Number(value.trim()));
    const normalZ = values.length === 16 ? values[10] : Number.NaN;
    if (Number.isFinite(normalZ)) {
      if (normalZ < -EDGE_EPSILON) return BACK;
      if (normalZ > EDGE_EPSILON) return FRONT;
      return prior;
    }
  }

  const flatMatch = text.match(/^matrix\((.*)\)$/i);
  if (flatMatch) {
    const values = flatMatch[1].split(',').map((value) => Number(value.trim()));
    if (values.length === 6 && values.every(Number.isFinite)) {
      const orientation = values[0] * values[3] - values[1] * values[2];
      if (orientation < -EDGE_EPSILON) return BACK;
      if (orientation > EDGE_EPSILON) return FRONT;
      return prior;
    }
  }

  const rotate = text.match(/rotateX\(\s*(-?[\d.]+)deg\s*\)/i);
  if (rotate) {
    const degrees = Number(rotate[1]);
    if (Number.isFinite(degrees)) {
      const normalZ = Math.cos((degrees * Math.PI) / 180);
      if (normalZ < -EDGE_EPSILON) return BACK;
      if (normalZ > EDGE_EPSILON) return FRONT;
    }
  }
  return prior;
}

function _face(side, src, alt) {
  const face = document.createElement('span');
  face.className = `df-coin3d__face df-coin3d__face--${side}`;
  face.setAttribute('data-coin-face', side);
  face.setAttribute('aria-hidden', 'true');
  const image = document.createElement('img');
  image.src = src;
  image.alt = alt || '';
  image.decoding = 'async';
  face.appendChild(image);
  return { face, image };
}

/**
 * Build a two-faced coin inside a rotor. Both artworks are always mounted and decoded; which one
 * is seen is decided by the rotor's pose alone (a rotor at rotateX(180deg) shows ETH). The
 * returned images may be re-pointed at any time; the plane that is edge-on or turned away shows
 * nothing, so a swap there is invisible.
 */
export function appendCoinFaces(rotor, {
  frontSrc = '/shared/coinflip-face-red.svg',
  backSrc = '/shared/coinflip-face-eth.svg',
  frontAlt = '',
  backAlt = '',
} = {}) {
  if (!rotor || typeof document === 'undefined') return null;
  const surface = document.createElement('span');
  surface.className = 'df-coin3d__surface';
  const front = _face(FRONT, frontSrc, frontAlt);
  const back = _face(BACK, backSrc, backAlt);
  surface.appendChild(front.face);
  surface.appendChild(back.face);
  rotor.appendChild(surface);
  return {
    surface,
    frontFace: front.face,
    backFace: back.face,
    frontImage: front.image,
    backImage: back.image,
  };
}
